const result = await browser.js(`(function(){
  const list = document.querySelectorAll('ol.references > li');
  const li = list[274]; // 275th, 0-indexed
  if(!li) return null;
  const id = li.id;
  const html = li.innerHTML;
  const text = li.textContent;
  // find links inside that point to sources section (usually #CITEREF...)
  const links = Array.from(li.querySelectorAll('a')).map(a => ({href: a.getAttribute('href'), text: a.textContent}));
  return { id, text, links };
})()`);
return result;

const result = await browser.js(`(function(){
  const el = document.getElementById('CITEREFChubarov2001');
  if(!el) return {found:false};
  // highlight class check
  const cls = el.className;
  const text = el.textContent.trim();
  const html = el.outerHTML;
  return { found:true, cls, text, html };
})()`);
return result;

// Click the link inside the 275th reference that points to sources
const clicked = await browser.js(`(function(){
  const list = document.querySelectorAll('ol.references > li');
  const li = list[274];
  const link = li.querySelector('a[href="#CITEREFChubarov2001"]');
  if(!link) return {found:false};
  link.click();
  return {found:true, href: link.getAttribute('href')};
})()`);
await new Promise(r => setTimeout(r, 500));
const check = await browser.js(`(function(){
  const el = document.getElementById('CITEREFChubarov2001');
  const rect = el.getBoundingClientRect();
  return { text: el.textContent.trim(), top: rect.top, inView: rect.top >=0 && rect.top < window.innerHeight };
})()`);
return { clicked, check, url: (await browser.js('location.href')) };

// scroll a bit to center it, then screenshot
await browser.js(`(function(){
  const el = document.getElementById('CITEREFChubarov2001');
  el.scrollIntoView({block:'center'});
})()`);
